source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_API_ID=}"
: "${MDF_ARTIFACT_ID?MDF_ARTIFACT_ID is required (Azure parameter artifactId)}"
: "${MDF_BG_ID?MDF_BG_ID is required (Azure parameter bgId)}"
: "${MDF_CONNECTED_APP_ID?MDF_CONNECTED_APP_ID is required (Azure parameter connectedAppId)}"
: "${MDF_CONNECTED_APP_SECRET?MDF_CONNECTED_APP_SECRET is required (Azure parameter connectedAppSecret)}"
: "${MDF_DEPLOYMENT_TARGET=ch2}"
: "${MDF_ENV_CLIENT_ID=}"
: "${MDF_ENV_CLIENT_SECRET=}"
: "${MDF_ENV_ID?MDF_ENV_ID is required (Azure parameter envId)}"
: "${MDF_ENV_NAME=}"
: "${MDF_ENV_SETTINGS_PATH?MDF_ENV_SETTINGS_PATH is required (Azure parameter envSettingsPath)}"
: "${MDF_IS_API_MANAGER=false}"
: "${MDF_MULE_ENV?MDF_MULE_ENV is required (Azure parameter muleEnv)}"
: "${MDF_SECURE_KEY=}"
: "${MDF_SETTINGS_XML=}"
