# >>> extracted body
set -euo pipefail

# ══════════════════════════════════════════════════════════════
# Pipeline Parameters
# ══════════════════════════════════════════════════════════════
ARTIFACT_ID="${MDF_ARTIFACT_ID}"
VERSION="${MDF_VERSION}"
DEPLOYMENT_TARGET="${MDF_DEPLOYMENT_TARGET}"
API_ID="${MDF_API_ID}"
IS_API_MANAGER="${MDF_IS_API_MANAGER}"
CONNECTED_APP_ID="${MDF_CONNECTED_APP_ID}"
CONNECTED_APP_SECRET="${MDF_CONNECTED_APP_SECRET}"
ENV_ID="${MDF_ENV_ID}"
ENV_NAME="${MDF_ENV_NAME}"
BG_ID="${MDF_BG_ID}"
SECURE_KEY="${MDF_SECURE_KEY}"
ENV_CLIENT_ID="${MDF_ENV_CLIENT_ID}"
ENV_CLIENT_SECRET="${MDF_ENV_CLIENT_SECRET}"
ENV_SETTINGS_PATH="$(ci_pipeline_workspace)/s/${MDF_ENV_SETTINGS_PATH}"
MULE_ENV="${MDF_MULE_ENV}"
ARTIFACTS_DIR="$(ci_pipeline_workspace)/mule-artifacts"

echo "[DEBUG] ============================================"
echo "[DEBUG] DEPLOY TO ${DEPLOYMENT_TARGET} START"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   artifactId=$ARTIFACT_ID"
echo "[DEBUG]   version=$VERSION"
echo "[DEBUG]   deploymentTarget=$DEPLOYMENT_TARGET"
echo "[DEBUG]   apiId=$API_ID"
echo "[DEBUG]   isApiManager=$IS_API_MANAGER"
echo "[DEBUG]   connectedAppId=${CONNECTED_APP_ID:0:8}*** (masked)"
echo "[DEBUG]   envId=$ENV_ID"
echo "[DEBUG]   envName=$ENV_NAME"
echo "[DEBUG]   bgId=$BG_ID"
echo "[DEBUG]   secureKey=${SECURE_KEY:+SET} (masked)"
echo "[DEBUG]   envClientId=${ENV_CLIENT_ID:0:8}*** (masked)"
echo "[DEBUG]   envSettingsPath=$ENV_SETTINGS_PATH"
echo "[DEBUG]   muleEnv=$MULE_ENV"
echo "[DEBUG]   artifactsDir=$ARTIFACTS_DIR"
echo "[DEBUG] ============================================"

# ══════════════════════════════════════════════════════════════
# Read settings.properties
# ══════════════════════════════════════════════════════════════
APP_NAME="$(ci_repo_name)"
SETTINGS_FILE="${ENV_SETTINGS_PATH}/${APP_NAME}/settings.properties"

echo "[DEBUG] APP_NAME=$APP_NAME"
echo "[DEBUG] SETTINGS_FILE=$SETTINGS_FILE (exists=$([ -f "$SETTINGS_FILE" ] && echo 'yes' || echo 'no'))"

# Helper: read a key from settings.properties with a default
read_setting() {
  local key="$1"
  local default="$2"
  if [[ -f "$SETTINGS_FILE" ]]; then
    local val
    val=$(grep "^${key}=" "$SETTINGS_FILE" | cut -d'=' -f2- | xargs)
    echo "${val:-$default}"
  else
    echo "$default"
  fi
}

if [[ -f "$SETTINGS_FILE" ]]; then
  echo "[DEBUG] settings.properties content:"
  echo "[DEBUG] $(cat "$SETTINGS_FILE")"
else
  echo "[DEBUG] settings.properties NOT FOUND — using all defaults"
  ci_log_warning "settings.properties not found at: $SETTINGS_FILE. Using defaults."
fi

# ══════════════════════════════════════════════════════════════
# Common settings (all targets)
# ══════════════════════════════════════════════════════════════
API_LAYER=$(read_setting "apiLayer" "")
API_TAGS=$(read_setting "apiTags" "")

# Lowercase env for deployment suffix
MULE_ENV_LOWER=$(echo "$MULE_ENV" | tr '[:upper:]' '[:lower:]')

# ══════════════════════════════════════════════════════════════
# Build Maven command — base args (shared across all targets)
# Profile activation tells POM which deployment type to use
# ══════════════════════════════════════════════════════════════
MVN_ARGS=(
  "mule:deploy"
  "-U"
  "-P" "${DEPLOYMENT_TARGET}"
  "-s" "${MDF_SETTINGS_XML}"
  "-Dmaven.repo.local=$(ci_pipeline_workspace)/.m2/repository"
  "-Ddeployment.connAppClientId=${CONNECTED_APP_ID}"
  "-Ddeployment.connAppClientSecret=${CONNECTED_APP_SECRET}"
  "-DorganizationId=${BG_ID}"
  "-Dmule.env=${MULE_ENV}"
  "-Ddeployment.suffix=-${MULE_ENV_LOWER}"
)

# ══════════════════════════════════════════════════════════════
# Target-specific args — each profile expects different properties
# ══════════════════════════════════════════════════════════════
if [[ "$DEPLOYMENT_TARGET" == "ch2" ]]; then
  # CloudHub 2.0 deployment name: strip 'mule-' prefix, skip suffix for PROD
  DEPLOY_APP_NAME="${ARTIFACT_ID#mule-}"
  if [[ "$MULE_ENV" != "PROD" ]]; then
    DEPLOY_APP_NAME="${DEPLOY_APP_NAME}-${MULE_ENV_LOWER}"
  fi
  if [[ ${#DEPLOY_APP_NAME} -gt 42 ]]; then
    ci_log_error "CloudHub 2.0 app name exceeds 42 chars: '${DEPLOY_APP_NAME}' (${#DEPLOY_APP_NAME} chars)"
    exit 1
  fi
  echo "[DEBUG] DEPLOY_APP_NAME=$DEPLOY_APP_NAME (${#DEPLOY_APP_NAME} chars)"

  # CH2 infrastructure from settings.properties
  SPACE=$(read_setting "deployment.space" "default")
  REPLICAS=$(read_setting "deployment.replica" "1")
  VCORES=$(read_setting "deployment.core" "0.1")
  GENERATE_PUBLIC_URL=$(read_setting "generateDefaultPublicUrl" "true")
  UPDATE_STRATEGY=$(read_setting "updateStrategy" "rolling")
  FORWARD_SSL=$(read_setting "forwardSslSession" "false")
  CLUSTERED=$(read_setting "clustered" "true")
  PERSISTENT_OBJECT_STORE=$(read_setting "persistentObjectStore" "false")
  PUBLIC_URL=$(read_setting "deployment.publicUrl" "")

  echo "[DEBUG] CH2 settings resolved:"
  echo "[DEBUG]   space=$SPACE, replicas=$REPLICAS, vCores=$VCORES"
  echo "[DEBUG]   publicUrl=$GENERATE_PUBLIC_URL, updateStrategy=$UPDATE_STRATEGY"
  echo "[DEBUG]   forwardSsl=$FORWARD_SSL, clustered=$CLUSTERED, objectStore=$PERSISTENT_OBJECT_STORE"

  MVN_ARGS+=(
    "-Ddeployment.name=${DEPLOY_APP_NAME}"
    "-DchEnv=${ENV_NAME}"
    "-Dmule.vault.key=${SECURE_KEY}"
    "-Ddeployment.space=${SPACE}"
    "-Ddeployment.replica=${REPLICAS}"
    "-Ddeployment.core=${VCORES}"
    "-DgenerateDefaultPublicUrl=${GENERATE_PUBLIC_URL}"
    "-DupdateStrategy=${UPDATE_STRATEGY}"
    "-DforwardSslSession=${FORWARD_SSL}"
    "-Dclustered=${CLUSTERED}"
    "-DpersistentObjectStore=${PERSISTENT_OBJECT_STORE}"
    "-DapiLayer=${API_LAYER}"
    "-DapiTags=${API_TAGS}"
  )

  # Custom public URL (only if set)
  if [[ -n "$PUBLIC_URL" ]]; then
    MVN_ARGS+=("-Ddeployment.publicUrl=${PUBLIC_URL}")
  fi

elif [[ "$DEPLOYMENT_TARGET" == "onprem" ]]; then
  # On-prem deployment name: strip 'mule-' prefix
  DEPLOY_APP_NAME="${ARTIFACT_ID#mule-}"
  if [[ "$MULE_ENV" != "PROD" ]]; then
    DEPLOY_APP_NAME="${DEPLOY_APP_NAME}-${MULE_ENV_LOWER}"
  fi
  echo "[DEBUG] DEPLOY_APP_NAME=$DEPLOY_APP_NAME"

  # On-prem infrastructure from settings.properties
  SERVER_NAME=$(read_setting "deployment.target" "")
  TARGET_TYPE=$(read_setting "deployment.targetType" "server")

  echo "[DEBUG] On-prem settings resolved:"
  echo "[DEBUG]   target=$SERVER_NAME, targetType=$TARGET_TYPE"

  if [[ -z "$SERVER_NAME" || "$SERVER_NAME" == __REQUIRED_SET_* ]]; then
    ci_log_error "deployment.target not set in settings.properties. Cannot deploy to on-prem."
    exit 1
  fi

  MVN_ARGS+=(
    "-Ddeployment.name=${DEPLOY_APP_NAME}"
    "-DonpremEnv=${ENV_NAME}"
    "-Dmule.vault.key=${SECURE_KEY}"
    "-Ddeployment.target=${SERVER_NAME}"
    "-Ddeployment.targetType=${TARGET_TYPE}"
    "-DapiLayer=${API_LAYER}"
    "-DapiTags=${API_TAGS}"
  )

elif [[ "$DEPLOYMENT_TARGET" == "rtf" ]]; then
  # RTF deployment name: strip 'mule-' prefix, skip suffix for PROD
  DEPLOY_APP_NAME="${ARTIFACT_ID#mule-}"
  if [[ "$MULE_ENV" != "PROD" ]]; then
    DEPLOY_APP_NAME="${DEPLOY_APP_NAME}-${MULE_ENV_LOWER}"
  fi
  echo "[DEBUG] DEPLOY_APP_NAME=$DEPLOY_APP_NAME"

  # Per-app/env infra from settings.properties (fixed standards live in the parent POM)
  RTF_TARGET=$(read_setting "deployment.target" "")
  REPLICAS=$(read_setting "deployment.replica" "1")
  UPDATE_STRATEGY=$(read_setting "updateStrategy" "rolling")
  CLUSTERED=$(read_setting "clustered" "false")
  PERSISTENT_OBJECT_STORE=$(read_setting "persistentObjectStore" "false")
  GENERATE_PUBLIC_URL=$(read_setting "generateDefaultPublicUrl" "false")
  FORWARD_SSL=$(read_setting "forwardSslSession" "false")
  CPU_RESERVED=$(read_setting "cpuReserved" "500m")
  CPU_LIMIT=$(read_setting "cpuLimit" "1000m")
  MEMORY_RESERVED=$(read_setting "memoryReserved" "700Mi")
  MEMORY_LIMIT=$(read_setting "memoryLimit" "700Mi")
  PUBLIC_URL=$(read_setting "deployment.publicUrl" "")

  echo "[DEBUG] RTF settings resolved:"
  echo "[DEBUG]   target=$RTF_TARGET, replicas=$REPLICAS, updateStrategy=$UPDATE_STRATEGY"
  echo "[DEBUG]   clustered=$CLUSTERED, objectStore=$PERSISTENT_OBJECT_STORE, generatePublicUrl=$GENERATE_PUBLIC_URL"
  echo "[DEBUG]   cpu=$CPU_RESERVED/$CPU_LIMIT, memory=$MEMORY_RESERVED/$MEMORY_LIMIT"

  if [[ -z "$RTF_TARGET" || "$RTF_TARGET" == __REQUIRED_SET_* ]]; then
    ci_log_error "deployment.target not set in settings.properties. Cannot deploy to RTF."
    exit 1
  fi

  MVN_ARGS+=(
    "-Ddeployment.name=${DEPLOY_APP_NAME}"
    "-DrtfEnv=${ENV_NAME}"
    "-Dmule.vault.key=${SECURE_KEY}"
    "-Ddeployment.target=${RTF_TARGET}"
    "-Ddeployment.replica=${REPLICAS}"
    "-DupdateStrategy=${UPDATE_STRATEGY}"
    "-Dclustered=${CLUSTERED}"
    "-DpersistentObjectStore=${PERSISTENT_OBJECT_STORE}"
    "-DgenerateDefaultPublicUrl=${GENERATE_PUBLIC_URL}"
    "-DforwardSslSession=${FORWARD_SSL}"
    "-DcpuReserved=${CPU_RESERVED}"
    "-DcpuLimit=${CPU_LIMIT}"
    "-DmemoryReserved=${MEMORY_RESERVED}"
    "-DmemoryLimit=${MEMORY_LIMIT}"
    "-DapiLayer=${API_LAYER}"
    "-DapiTags=${API_TAGS}"
  )

  # Custom public URL (only if set)
  if [[ -n "$PUBLIC_URL" ]]; then
    MVN_ARGS+=("-Ddeployment.publicUrl=${PUBLIC_URL}")
  fi

else
  ci_log_error "Unknown deploymentTarget: ${DEPLOYMENT_TARGET}. Expected: ch2, onprem, rtf"
  exit 1
fi

# ══════════════════════════════════════════════════════════════
# API Manager args (conditional — all targets)
# ══════════════════════════════════════════════════════════════
if [[ "$IS_API_MANAGER" == "true" ]]; then
  MVN_ARGS+=(
    "-Dapi.autodiscoveryID=${API_ID}"
    "-Danypoint_platform_client_id=${ENV_CLIENT_ID}"
    "-Danypoint_platform_client_secret=${ENV_CLIENT_SECRET}"
  )
  echo "[DEBUG] API Manager autodiscovery enabled: api.id=${API_ID}"
else
  echo "[DEBUG] API Manager skipped (is.api.manager=false)"
fi

# ══════════════════════════════════════════════════════════════
# Deploy POM reference (Exchange artifact from pre-deploy)
# ══════════════════════════════════════════════════════════════
DEPLOY_POM="$ARTIFACTS_DIR/deploy-pom.xml"
if [[ -f "$DEPLOY_POM" ]]; then
  MVN_ARGS+=("-f" "$DEPLOY_POM")
  echo "[DEBUG] Using deploy POM: $DEPLOY_POM"
else
  echo "[DEBUG] No deploy-pom.xml — deploying from local artifact"
fi

# ══════════════════════════════════════════════════════════════
# Execute deployment
# ══════════════════════════════════════════════════════════════
echo "[DEBUG] Full mvn command (secrets masked):"
echo "[DEBUG]   mvn ${MVN_ARGS[*]}" | sed 's/connAppClientSecret=[^ ]*/connAppClientSecret=***/g; s/vault.key=[^ ]*/vault.key=***/g; s/client_secret=[^ ]*/client_secret=***/g'
echo "Deploying ${ARTIFACT_ID} v${VERSION} to ${DEPLOYMENT_TARGET} (${MULE_ENV})..."

mvn "${MVN_ARGS[@]}"

echo "Deployment successful: ${ARTIFACT_ID} → ${DEPLOYMENT_TARGET} (${MULE_ENV})"
echo "[DEBUG] DEPLOY TO ${DEPLOYMENT_TARGET} COMPLETE"
# <<< extracted body
